<section class="panel"><div class="panel-heading"><div><h2>Selling variants</h2><p>Prices are INR per selling unit. Coverage is square feet per box/slab. Dimensions are millimetres.</p></div><button type="button" class="button secondary" id="add-variant">＋ Add variant</button></div><p class="help-text">A published material needs an enabled variant. Units and coverage cannot change after stock history exists. Removing a saved variant disables it while preserving history.</p><div id="variant-rows"><?php foreach($rows as $i=>$row): ?><?php if(!is_array($row))continue; ?><article class="variant-row"><div class="variant-heading"><h3>Variant <span class="variant-number"><?= $i+1 ?></span></h3><button type="button" class="text-button remove-variant">Remove variant</button></div><?php if(!empty($row['id']))$hidden(["variants[$i][id]"=>$row['id']]); ?><div class="form-grid three"><?php $field("variants[$i][sku]",'SKU',$row['sku']??'','text','required maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9_.-]*"',"variants.$i.sku");$field("variants[$i][finish]",'Finish',$row['finish']??'','text','maxlength="80"',"variants.$i.finish"); ?><label class="field"><span>Selling unit</span><select name="variants[<?= $i ?>][sell_unit]" class="variant-unit"><?php foreach(['sqft'=>'Square feet','slab'=>'Slab','box'=>'Box'] as $unit=>$label): ?><option value="<?= $unit ?>" <?= ($row['sell_unit']??'sqft')===$unit?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><?php foreach(['original_price'=>['Original reference price (INR, optional)','min="0" step="0.01" max="10000000000"'],'price'=>['Price per unit (INR)','required min="0" step="0.01" max="10000000000"'],'increment'=>['Minimum quantity increment','required min="0.001" step="0.001" max="1000"'],'coverage'=>['Coverage per unit (sq ft)','min="0.001" step="0.001" max="1000000"'],'thickness'=>['Thickness (mm)','min="0.001" step="0.001" max="1000000"'],'length'=>['Length (mm)','min="0.001" step="0.001" max="1000000"'],'width'=>['Width (mm)','min="0.001" step="0.001" max="1000000"']] as $name=>[$label,$attributes]): ?><?php $field("variants[$i][$name]",$label,$row[$name]??'','number',$attributes,"variants.$i.$name"); ?><?php endforeach; ?><label class="field"><span>Variant availability</span><select name="variants[<?= $i ?>][enabled]"><option value="1" <?= ($row['enabled']??1)==1?'selected':'' ?>>Enabled</option><option value="0" <?= ($row['enabled']??1)==0?'selected':'' ?>>Disabled</option></select></label></div></article><?php endforeach; ?></div><input type="hidden" name="variant_count" id="variant-count" value="<?= count($rows) ?>"></section>
