<?php if($product): ?><section class="panel"><div class="panel-heading"><div><h2>Product photographs</h2><p>Up to 12 original images. Uploads are validated and re-encoded before publishing.</p></div><span class="pill"><?= count($product['images']) ?>/12 IMAGES</span></div><div class="image-grid"><?php foreach($product['images'] as $image): ?><article><img src="<?= $u($image['path']) ?>" alt="<?= $e($image['alt_text']) ?>"><p><?= $e($image['alt_text']) ?></p><?php if($editable): ?><form method="post" action="<?= $u('admin/product/image') ?>" data-confirm="Remove this product image?"><?php $hidden(['csrf'=>$csrf,'id'=>$product['id'],'action'=>'remove','image_id'=>$image['id'],'operation_key'=>$key()]); ?><button class="text-button danger">Remove image</button></form><?php endif; ?></article><?php endforeach; ?></div><?php if($editable): ?><?php if(ProductImageService::available()): ?><form method="post" action="<?= $u('admin/product/image') ?>" enctype="multipart/form-data" data-validate><?php $hidden(['csrf'=>$csrf,'id'=>$product['id'],'operation_key'=>$key()]); ?><div class="form-grid"><label class="field"><span>Original product image *</span><input type="file" name="image" accept="image/jpeg,image/png,image/webp" required><small>JPEG, PNG or WebP. Maximum 4 MB, 6000px per side and 12 megapixels.</small></label><?php $field('alt_text','Image description','','text','required maxlength="190"');$field('position','Gallery position','0','number','required min="0" max="1000" step="1"'); ?><label class="field"><span>Variant (optional)</span><select name="variant_id"><option value="">All variants</option><?php foreach($product['variants'] as $variant): ?><option value="<?= $e($variant['id']) ?>"><?= $e($variant['sku']) ?></option><?php endforeach; ?></select></label></div><button class="button">Upload photograph</button></form><?php else: ?><p class="notice">Image uploads are unavailable because PHP GD is not enabled. Ask the server operator to enable GD, then reload this page.</p><?php endif; ?><?php endif; ?></section><?php if($editable&&$product['status']!=='archived'): ?><section class="panel archive-panel"><div><h2>Archive this material</h2><p>Remove it from public browsing while preserving existing order history.</p></div><form method="post" action="<?= $u('admin/product/archive') ?>" data-confirm="Archive this material and hide it from the storefront?"><?php $hidden(['csrf'=>$csrf,'id'=>$product['id'],'revision'=>$product['revision'],'operation_key'=>$key()]); ?><button class="button danger secondary">Archive material</button></form></section><?php endif; ?><?php endif; ?>
